1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	// One row per item type the office recognises. Base premium (what it costs to
58	// insure) and insurance value (what it is insured FOR) are independent numbers,
59	// but they are known for exactly the same set of types — so they belong in one
60	// table. Keeping them apart would leave two key sets that must agree with
61	// nothing enforcing it.
62	interface ItemSpec {
63	  basePremium: number;
64	  insuranceValue: number;
65	  isComponent: boolean;
66	}
67	
68	const ITEM_SPECS = {
69	  sword: { basePremium: 100, insuranceValue: 1000, isComponent: false },
70	  amulet: { basePremium: 60, insuranceValue: 600, isComponent: false },
71	  staff: { basePremium: 80, insuranceValue: 800, isComponent: false },
72	  potion: { basePremium: 40, insuranceValue: 400, isComponent: false },
73	  rune: { basePremium: 25, insuranceValue: 250, isComponent: true },
74	  moonstone: { basePremium: 25, insuranceValue: 250, isComponent: true },
75	} as const satisfies Record<string, ItemSpec>;
76	
77	type KnownItemType = keyof typeof ITEM_SPECS;
78	
79	const isKnownItemType = (type: string): type is KnownItemType =>
80	  type in ITEM_SPECS;
81	
82	// The office insures only what its price list names. An unknown type has no
83	// premium and no insurance value, so there is nothing to quote — the whole
84	// scenario is rejected rather than priced at zero.
85	const specForItem = (item: Item): ItemSpec => {
86	  if (!isKnownItemType(item.type)) {
87	    throw new Error(`The MHPCO does not insure items of type ${item.type}`);
88	  }
89	  return ITEM_SPECS[item.type];
90	};
91	
92	const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;
93	
94	const BLOCK_SIZE = 3;
95	
96	const BLOCK_BASE_PREMIUM = 60;
97	
98	const sum = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	// "Alike" means the same exact type, not merely the same family: two runes and
102	// a moonstone are three components but not three alike ones, so grouping them
103	// by type keeps them apart and denies them the block price.
104	const groupByType = (items: Item[]): Item[][] => {
105	  const groups = new Map<string, Item[]>();
106	  for (const item of items) {
107	    const group = groups.get(item.type);
108	    if (group) {
109	      group.push(item);
110	    } else {
111	      groups.set(item.type, [item]);
112	    }
113	  }
114	  return [...groups.values()];
115	};
116	
117	// A block is three alike COMPONENTS — the discount is offered on runes and
118	// moonstones, not on swords. It is also not carved out of a larger group: the
119	// price applies only when the group holds exactly three (7 runes cost 7 × 25,
120	// not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only ever
121	// passes a single group from groupByType.
122	const isComponent = (item: Item): boolean => specForItem(item).isComponent;
123	
124	const isBlock = (group: Item[]): boolean =>
125	  group.length === BLOCK_SIZE && group.every(isComponent);
126	
127	const basePremiumForGroup = (group: Item[]): number =>
128	  isBlock(group) ? BLOCK_BASE_PREMIUM : sum(group.map(basePremiumForItem));
129	
130	const basePremiumForItems = (items: Item[]): number =>
131	  sum(groupByType(items).map(basePremiumForGroup));
132	
133	const CURSE_SURCHARGE = 0.5;
134	
135	// Every modifier is an additive percentage of its OWN base — modifiers never
136	// compound with each other. Item-scoped modifiers take the affected item's base
137	// premium as their base; policy-scoped modifiers take the policy base premium
138	// (the sum of all item base premiums). So the total is always
139	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
140	const modifierAmount = (rate: number, base: number): number => rate * base;
141	
142	const ENCHANTMENT_SURCHARGE = 0.3;
143	
144	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
145	
146	const isCursed = (item: Item): boolean => item.cursed === true;
147	
148	const attractsEnchantmentSurcharge = (item: Item): boolean =>
149	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL;
150	
151	interface ItemModifier {
152	  rate: number;
153	  appliesTo: (item: Item) => boolean;
154	}
155	
156	// Each item-scoped modifier is a row: a rate and the condition under which it
157	// applies. The predicate names the modifier, so a row needs no separate label.
158	// Adding a modifier means adding a row, not a new branch.
159	const ITEM_MODIFIERS: ItemModifier[] = [
160	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
161	  { rate: ENCHANTMENT_SURCHARGE, appliesTo: attractsEnchantmentSurcharge },
162	];
163	
164	const itemModifierRates = (item: Item): number[] =>
165	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
166	    (modifier) => modifier.rate,
167	  );
168	
169	const LOYALTY_DISCOUNT = 0.2;
170	
171	const LOYALTY_THRESHOLD_YEARS = 2;
172	
173	const isLongStanding = (customer: Customer): boolean =>
174	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
175	
176	// Discounts are surcharges with the sign flipped: expressing one as a negative
177	// rate lets it flow through the same additive sum as every surcharge, with no
178	// separate subtraction step. Discount constants stay positive magnitudes and
179	// are negated here, at the point of use, so the direction is visible in the
180	// rate list rather than buried in a constant's sign.
181	const asDiscount = (rate: number): number => -rate;
182	
183	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
184	
185	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
186	
187	// Policy-scoped modifiers apply to the policy base premium. Unlike item
188	// modifiers they select on the customer and on the quote's position in the
189	// scenario rather than on an item.
190	//
191	// The initial-assessment surcharge applies to every quote: each item is treated
192	// as a first insurance regardless of customer history. The follow-up discount
193	// is what distinguishes a customer's later contracts.
194	const policyModifierRates = (
195	  customer: Customer,
196	  isFollowUpContract: boolean,
197	): number[] => [
198	  INITIAL_ASSESSMENT_SURCHARGE,
199	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
200	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
201	];
202	
203	const itemModifiersTotal = (items: Item[]): number =>
204	  sum(
205	    items.flatMap((item) =>
206	      itemModifierRates(item).map((rate) =>
207	        modifierAmount(rate, basePremiumForItem(item)),
208	      ),
209	    ),
210	  );
211	
212	const policyModifiersTotal = (
213	  policyBasePremium: number,
214	  customer: Customer,
215	  isFollowUpContract: boolean,
216	): number =>
217	  sum(
218	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
219	      modifierAmount(rate, policyBasePremium),
220	    ),
221	  );
222	
223	// All amounts are rounded to whole G in the MHPCO's favour. Which way that
224	// points depends on which way the money flows: a premium comes in, so it rounds
225	// up; a payout goes out, so it rounds down.
226	//
227	// Two functions rather than one taking a direction, so that knowing which way
228	// favour points for a given kind of money stays here. A direction parameter
229	// would push that back onto every caller — the one thing these exist to answer.
230	const roundPremiumInMHPCOsFavour = (amount: number): number =>
231	  Math.ceil(amount);
232	
233	const roundPayoutInMHPCOsFavour = (amount: number): number =>
234	  Math.floor(amount);
235	
236	const quotePremium = (
237	  items: Item[],
238	  customer: Customer,
239	  isFollowUpContract: boolean,
240	): number => {
241	  const policyBasePremium = basePremiumForItems(items);
242	  return roundPremiumInMHPCOsFavour(
243	    policyBasePremium +
244	      itemModifiersTotal(items) +
245	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
246	      PROCESSING_FEE,
247	  );
248	};
249	
250	const insuranceValueForItem = (item: Item): number =>
251	  specForItem(item).insuranceValue;
252	
253	// Deliberately NOT the shape of basePremiumForItems. Both aggregate a per-item
254	// figure from ITEM_SPECS, but the premium side groups by type first so a block
255	// of three alike components can be priced as one; this side never groups. Three
256	// runes cost 60 to insure and are insured for 3 × 250 = 750. The block is a
257	// discount on the price of cover, not a reduction of the cover bought.
258	//
259	// So the near-symmetry is a false friend: factoring the two into one traversal
260	// would read as tidier and would silently make blocks shrink the insurance sum.
261	// The repetition of `sum(items.map(...))` is the price of keeping them free to
262	// diverge, and is paid on purpose.
263	const insuranceSum = (items: Item[]): number =>
264	  sum(items.map(insuranceValueForItem));
265	
266	const CAP_MULTIPLE = 2;
267	
268	// The cap is twice the insurance sum — the value the items are insured FOR, so
269	// it is computed from the items alone and never from the premium. Curses,
270	// enchantments and loyalty change what a policy costs without changing what it
271	// covers (as do blocks — see insuranceSum). Naming the relation keeps that
272	// separation visible at the one place a policy is created.
273	const capForItems = (items: Item[]): number =>
274	  CAP_MULTIPLE * insuranceSum(items);
275	
276	const DEDUCTIBLE = 100;
277	
278	interface Policy {
279	  items: Item[];
280	  remainingCap: number;
281	}
282	
283	// Steps are not independent: a quote's premium depends on how many quotes came
284	// before it, and a claim draws down the cap of a policy an earlier quote
285	// created. So a step is a function from state to (result, next state), and the
286	// scenario is a fold over that — not a map, which would promise an independence
287	// the steps do not have.
288	//
289	// Policies are keyed by the index of the quote step that created them: a claim
290	// step names its policy by that zero-based index.
291	interface ScenarioState {
292	  quotesSoFar: number;
293	  policies: Map<number, Policy>;
294	}
295	
296	// A fresh state per run, not a shared constant. The Map makes the difference:
297	// a module-level seed would hand every scenario the same one. Nothing mutates
298	// it today — withPolicy copies before it writes — so a shared seed would work,
299	// but only by an invariant that lives in another function and would have to be
300	// rediscovered by the next writer. Building the seed per run makes each
301	// scenario's independence a property of the code rather than a promise about it.
302	const initialState = (): ScenarioState => ({
303	  quotesSoFar: 0,
304	  policies: new Map(),
305	});
306	
307	interface StepOutcome {
308	  result: StepResult;
309	  state: ScenarioState;
310	}
311	
312	// Both operations end by filing a policy under its quote's index — a claim
313	// re-files the same policy with a drawn-down cap. Naming that once keeps the
314	// Map out of the operations, so neither has to know how policies are stored.
315	const withPolicy = (
316	  state: ScenarioState,
317	  policyIndex: number,
318	  policy: Policy,
319	): ScenarioState => ({
320	  ...state,
321	  policies: new Map(state.policies).set(policyIndex, policy),
322	});
323	
324	// What makes a contract a follow-up is that the customer has already been
325	// quoted in this scenario — the first quote is the initial contract, every
326	// later one follows it. Named because the bare comparison is the
327	// follow-up-contract rule itself, not an index check: it is what decides
328	// whether the 15 % discount applies.
329	const isFollowUpContract = (state: ScenarioState): boolean =>
330	  state.quotesSoFar > 0;
331	
332	const runQuote = (
333	  step: QuoteStep,
334	  customer: Customer,
335	  state: ScenarioState,
336	  stepIndex: number,
337	): StepOutcome => ({
338	  result: {
339	    premium: quotePremium(step.items, customer, isFollowUpContract(state)),
340	  },
341	  state: withPolicy(
342	    { ...state, quotesSoFar: state.quotesSoFar + 1 },
343	    stepIndex,
344	    {
345	      items: step.items,
346	      remainingCap: capForItems(step.items),
347	    },
348	  ),
349	});
350	
351	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
352	
353	const REDUCED_REIMBURSEMENT_RATE = 0.5;
354	
355	const FULL_REIMBURSEMENT_RATE = 1;
356	
357	// Reads enchantment like the premium-side surcharge rule, but is a different
358	// rule with its own level: this one halves what a claim pays out, that one
359	// raises what a policy costs. Sharing a predicate would tie two levels that the
360	// spec lets move independently, so the shape is repeated deliberately.
361	const qualifiesForReducedReimbursement = (item: Item): boolean =>
362	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
363	
364	// The reimbursement rate is decided first, then one deductible comes off.
365	//
366	// The dragon-material clause is absent on purpose, not by oversight. It promises
367	// full reimbursement of the damage before the deductible — which is exactly what
368	// FULL_REIMBURSEMENT_RATE already gives every item that misses the reduced-rate
369	// clause. Where both clauses apply the spec awards it to the 50 % rule. Between
370	// them the two facts leave the clause with no input it can move: dragon material
371	// at enchantment 9 or 8 pays the same 400 as steel at those levels, and at
372	// enchantment 5 it pays the same 700 steel would. Writing it as its own branch
373	// would add a branch no test could ever tell from the default — a distinction
374	// the domain does not make.
375	const reimbursementRate = (item: Item): number =>
376	  qualifiesForReducedReimbursement(item)
377	    ? REDUCED_REIMBURSEMENT_RATE
378	    : FULL_REIMBURSEMENT_RATE;
379	
380	const payoutForDamage = (damage: Damage, item: Item): number =>
381	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
382	
383	// Returns AN insured item of the damaged type, not THE damaged one — a policy
384	// can cover two swords, so the type does not name a unique item. Two damage
385	// entries of the same type are both answered with the same first match.
386	//
387	// That is sound today because the answer is used solely to read payout
388	// attributes (the reimbursement rate), and the covered case — two damages
389	// against two swords — insures identical swords, which read the same either
390	// way. The deductible is charged per damage entry, not per matched item, so
391	// counting is unaffected too.
392	//
393	// One thing would break it, not yet under test: two swords with DIFFERENT
394	// attributes (say enchantment 3 and 9). Both damages would take the first
395	// sword's rate; the second should take its own. This lookup must then become a
396	// pairing that consumes what it matches. The honest name marks that spot.
397	//
398	// The `!` is a proof, not an assumption: rejectUnmatchedDamages runs first and
399	// throws unless every claimed type is covered at least as many times as it is
400	// named — so by the time this runs, a match exists for every damage entry. Both
401	// ways it could fail are covered by tests: claiming a type more often than it is
402	// insured, and claiming a type the policy does not cover at all.
403	const anInsuredItemOfDamagedType = (policy: Policy, damage: Damage): Item =>
404	  policy.items.find((item) => item.type === damage.itemType)!;
405	
406	// Counts how many times each value occurs. Deliberately typed on strings rather
407	// than on Item: the guard below tallies two different things (item types held
408	// and item types named by damages) and only their counts are ever compared, so
409	// the tally has no business knowing what the strings mean.
410	const tally = (values: string[]): Map<string, number> => {
411	  const counts = new Map<string, number>();
412	  for (const value of values) {
413	    counts.set(value, (counts.get(value) ?? 0) + 1);
414	  }
415	  return counts;
416	};
417	
418	// Every damage entry must claim an insured item of its own, so a type cannot be
419	// damaged more times than the policy covers it. One rule, three error cases the
420	// spec states separately — all of them the same comparison at different counts:
421	//
422	//   claimed > insured, insured ≥ 1  a type damaged more often than it is insured
423	//   claimed > insured, insured = 0  a type the policy does not cover at all
424	//   claimed > insured, insured = 0  a type the office does not insure at all
425	//
426	// The last two differ only in why the count is zero, which is why neither needs
427	// its own test. An uninsured type and an unknown type are both covered 0 times
428	// against a claimed 1. In particular the unknown type never reaches a lookup in
429	// ITEM_SPECS: a broomstick is not in THIS policy, which is the more precise
430	// complaint than whether the office insures broomsticks in general. The quote
431	// path is where the price list is consulted and where an unknown type is
432	// rejected as uninsurable.
433	//
434	// Checked before any payout is computed: the spec rejects the whole claim, not
435	// just the surplus entries.
436	const rejectUnmatchedDamages = (policy: Policy, incident: Incident): void => {
437	  const insured = tally(policy.items.map((item) => item.type));
438	  const claimed = tally(incident.damages.map((damage) => damage.itemType));
439	  for (const [type, claimedCount] of claimed) {
440	    const insuredCount = insured.get(type) ?? 0;
441	    if (claimedCount > insuredCount) {
442	      throw new Error(
443	        `Policy covers ${insuredCount} ${type}(s) but the claim names ${claimedCount}`,
444	      );
445	    }
446	  }
447	};
448	
449	// A damage is what an incident cost the owner, so it cannot be negative. Zero
450	// is left alone: the spec forbids only negative amounts, and a zero damage
451	// simply pays nothing once the deductible bites.
452	const isNegative = (damage: Damage): boolean => damage.amount < 0;
453	
454	const rejectNegativeDamages = (incident: Incident): void => {
455	  const negative = incident.damages.find(isNegative);
456	  if (negative) {
457	    throw new Error(
458	      `Damage to ${negative.itemType} is negative: ${negative.amount}`,
459	    );
460	  }
461	};
462	
463	// Both guards run before any payout is computed: the spec rejects the whole
464	// claim, not just the offending entries, so a valid entry alongside an invalid
465	// one must not be paid.
466	//
467	// They are two statements rather than a list of validations. Their signatures
468	// differ (only the first needs the policy), so a uniform list could hold them
469	// only by giving the second a parameter it ignores. And the order is not
470	// incidental: rejectUnmatchedDamages must come first because it is what makes
471	// the lookup in anInsuredItemOfDamagedType total — an obligation that reads as
472	// a sequenced line here but would vanish into array order in a list.
473	//
474	// Two is the whole set, not a stage on the way to more. The spec's remaining
475	// claim-side error — a damage naming an item type the office does not insure —
476	// needs no guard of its own: rejectUnmatchedDamages already catches it, because
477	// a type the office does not insure cannot be in the policy either and so is
478	// covered zero times. See its comment for why that is the more precise
479	// diagnosis rather than a lucky accident.
480	const payoutForIncident = (policy: Policy, incident: Incident): number => {
481	  rejectUnmatchedDamages(policy, incident);
482	  rejectNegativeDamages(incident);
483	  return sum(
484	    incident.damages.map((damage) =>
485	      payoutForDamage(damage, anInsuredItemOfDamagedType(policy, damage)),
486	    ),
487	  );
488	};
489	
490	// The damage decides what a claim is WORTH; the cap decides what there is left
491	// to pay it WITH. Once the cap is spent the office pays what remains, not what
492	// was asked — so the cap bounds the payout before it is charged against it.
493	//
494	// This is the guarantee that makes drawDownCap's subtraction safe: a payout that
495	// has passed through here can never exceed the balance, so the balance can never
496	// go negative. The two are a pair — bound, then spend — and neither is sound
497	// without the other.
498	const payoutWithinCap = (payout: number, remainingCap: number): number =>
499	  Math.min(payout, remainingCap);
500	
501	// A policy's cap is a balance, not a per-claim limit: each claim spends part of
502	// it and the rest carries forward to the next claim against the same policy.
503	// The balance stays non-negative because payoutWithinCap has already bounded
504	// what is spent — this subtraction does not defend itself, it relies on that.
505	//
506	// Naming the draw-down separates what the cap DOES from how a claim is assembled
507	// — the one line in runClaim that was arithmetic rather than plumbing.
508	const drawDownCap = (remainingCap: number, payout: number): number =>
509	  remainingCap - payout;
510	
511	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
512	  // A claim naming a policy that does not exist is a spec error case, but no
513	  // test drives it yet. The assertion stands in until one does — at which point
514	  // the missing case becomes the error branch rather than a crash.
515	  const policy = state.policies.get(step.policy)!;
516	  // Rounded before the clamp so the cap is only ever compared with, and reduced
517	  // by, whole G — a fractional payout would otherwise leave a fractional cap
518	  // behind for the next claim.
519	  const claimWorth = roundPayoutInMHPCOsFavour(
520	    payoutForIncident(policy, step.incident),
521	  );
522	  const payout = payoutWithinCap(claimWorth, policy.remainingCap);
523	  const remainingCap = drawDownCap(policy.remainingCap, payout);
524	  return {
525	    result: { payout, remainingCap },
526	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
527	  };
528	};
529	
530	// Dispatch decides once what a step is; each operation then owns both its
531	// result and how it advances the state, so no caller has to re-test step.op to
532	// know what the step did.
533	const runStep = (
534	  step: Step,
535	  customer: Customer,
536	  state: ScenarioState,
537	  stepIndex: number,
538	): StepOutcome =>
539	  step.op === "quote"
540	    ? runQuote(step, customer, state, stepIndex)
541	    : runClaim(step, state);
542	
543	// The fold carries both halves of the outcome: the results accumulated so far
544	// and the state the next step will see. Threading the state explicitly (rather
545	// than recovering it from the last result) keeps the dependency between steps
546	// visible in the type.
547	interface ScenarioRun {
548	  results: StepResult[];
549	  state: ScenarioState;
550	}
551	
552	const initialRun = (): ScenarioRun => ({ results: [], state: initialState() });
553	
554	const appendStep =
555	  (customer: Customer) =>
556	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
557	    const outcome = runStep(step, customer, run.state, stepIndex);
558	    return {
559	      results: [...run.results, outcome.result],
560	      state: outcome.state,
561	    };
562	  };
563	
564	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
565	  results: steps.reduce(appendStep(customer), initialRun()).results,
566	});
567

275:    it("a customer with 1 year with MHPCO gets no loyalty discount", () => {
283:    it("the first quote carries the 10 % initial assessment surcharge", () => {
297:    it("each quote after the first gets an additional 15 % follow-up contract discount", () => {
308:    it("the 5 G processing fee is added at the very end", () => {
328:    it("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)", () => {
343:    it("intermediate amounts are kept as fractions; only the final premium is rounded", () => {
360:    it("newcomer (0 years, first contract) with a cursed sword (steel, enchantment 3) → premium 165 G", () => {
